/**
 * k6 load-test route coverage audit: which catalog routes — method AND path — the k6 scenarios call.
 *
 * Reads docs/routes.txt (generated by `pnpm routes:catalog`) and every scenario file under
 * src/tests/load/k6/scenarios/, extracts the requests each scenario makes, and matches them to
 * catalog routes (a `:param` segment matches any value). A request is:
 *   - a direct call, `http.get|post|put|patch|del(<url>, …)` — the URL literal, or the literal a
 *     `const` of that name holds;
 *   - a `'METHOD', <path>` pair, as table-driven scenarios (fe-full-surface, comprehensive-journey)
 *     feed their generic caller.
 *
 * `--nightly` narrows the scenario set to the files `.github/workflows/scheduled-k6-load-slo.yml`
 * runs — what the nightly actually load-tests, rather than what some scenario file could.
 *
 * Excluded from the required set:
 *   - ROLE: super_admin / admin — needs an elevated token the scenarios do not hold
 *   - TOKEN: internal/ops credentials
 *   - PUBLIC infrastructure routes (OAuth, email sign-in, WebAuthn, Stripe webhook, health,
 *     password reset) that are not realistic load targets
 *
 * Usage:
 *   node tooling/ci/check-load-coverage.mjs                 # exits non-zero below --threshold
 *   node tooling/ci/check-load-coverage.mjs --report-only   # never exits non-zero
 *   node tooling/ci/check-load-coverage.mjs --nightly       # only what the nightly workflow runs
 *   node tooling/ci/check-load-coverage.mjs --threshold 60  # override minimum %
 */

import { readFileSync, readdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const ROOT = resolve(new URL('.', import.meta.url).pathname, '../..');
const ROUTES_FILE = join(ROOT, 'docs/routes.txt');
const SCENARIOS_DIR = join(ROOT, 'src/tests/load/k6/scenarios');
const NIGHTLY_WORKFLOW_FILE = join(ROOT, '.github/workflows/scheduled-k6-load-slo.yml');
const DEFAULT_THRESHOLD = 50; // % of required routes that must appear in ≥1 scenario

// --------------------------------------------------------------------------
// Route catalog
// --------------------------------------------------------------------------

// METHOD  PATH  S(tatus)  I(dempotency)  O(rganization scope)  AUTH — AUTH may contain spaces.
const ROUTE_LINE_RE = /^\s+(GET|POST|PUT|PATCH|DELETE)\s+(\/\S+)\s+\d{3}\s+\S+\s+\S+\s+(.+?)\s*$/;

/** Parses the catalog table: one `{ method, path, auth }` per route line. */
export function parseRoutes(content) {
  return content
    .split('\n')
    .map((line) => ROUTE_LINE_RE.exec(line))
    .filter(Boolean)
    .map((match) => ({ method: match[1], path: match[2], auth: match[3] }));
}

const PUBLIC_INFRASTRUCTURE_PATHS = [
  '/auth/oauth',
  '/auth/email/send-code',
  '/auth/email/login',
  '/auth/mfa/login',
  '/auth/password/forgot',
  '/auth/password/reset',
  '/auth/webauthn',
  '/auth/refresh',
  '/billing/webhook',
  '/tenancy/invitations/',
  '/livez',
  '/readyz',
  '/mcp',
];

/** True for routes k6 coverage is not required for (see the file header). */
export function isExcluded({ auth, path }) {
  if (auth.startsWith('ROLE:')) return true;
  if (auth.startsWith('TOKEN:')) return true;
  return auth === 'PUBLIC' && PUBLIC_INFRASTRUCTURE_PATHS.some((prefix) => path.includes(prefix));
}

// --------------------------------------------------------------------------
// Scenario requests
// --------------------------------------------------------------------------

const STRING_LITERAL = String.raw`(\x60[^\x60]*\x60|'[^']*'|"[^"]*")`;
const HTTP_VERB_TO_METHOD = { get: 'GET', post: 'POST', put: 'PUT', patch: 'PATCH', del: 'DELETE' };
const DIRECT_CALL_RE = new RegExp(
  String.raw`http\.(get|post|put|patch|del)\(\s*(?:${STRING_LITERAL}|([A-Za-z_$][\w$]*))`,
  'g',
);
const METHOD_PATH_PAIR_RE = new RegExp(
  String.raw`['"](GET|POST|PUT|PATCH|DELETE)['"]\s*,\s*${STRING_LITERAL}`,
  'g',
);

/**
 * Turns a scenario URL literal (quotes included) into a catalog-comparable path — `${API_PREFIX}`
 * and friends stripped, every other `${…}` a `:param`, no query string — or null when it is no path.
 */
export function normalizeScenarioPath(literal) {
  let path = literal.slice(1, -1);
  path = path.replace(/^\$\{[A-Z_]+\}/, '');
  path = path.replace(/^https?:\/\/[^/]+/, '');
  path = path.replace(/^\/api\/v\d+/, '');
  path = path.split('?')[0];
  path = path.replace(/\$\{[^}]*\}/g, ':param');
  return path.startsWith('/') ? path : null;
}

function resolveConstant(content, identifier) {
  const match = new RegExp(
    String.raw`(?:const|let|var)\s+${identifier}\s*=\s*${STRING_LITERAL}`,
  ).exec(content);
  return match ? match[1] : null;
}

/** Every `{ method, path }` request a scenario file makes (see the file header for the forms). */
export function extractScenarioRequests(content) {
  const requests = [];
  for (const match of content.matchAll(DIRECT_CALL_RE)) {
    const literal = match[2] ?? resolveConstant(content, match[3]);
    const path = literal ? normalizeScenarioPath(literal) : null;
    if (path) requests.push({ method: HTTP_VERB_TO_METHOD[match[1]], path });
  }
  for (const match of content.matchAll(METHOD_PATH_PAIR_RE)) {
    const path = normalizeScenarioPath(match[2]);
    if (path) requests.push({ method: match[1], path });
  }
  return requests;
}

// --------------------------------------------------------------------------
// Scenario sets
// --------------------------------------------------------------------------

/** Every scenario file: `{ name, content }`. */
export function loadScenarioFiles() {
  return readdirSync(SCENARIOS_DIR)
    .filter((name) => name.endsWith('.js'))
    .sort()
    .map((name) => ({ name, content: readFileSync(join(SCENARIOS_DIR, name), 'utf8') }));
}

/** The scenario file names the nightly workflow runs. */
export function nightlyScenarioNames(workflowContent) {
  return [
    ...new Set(
      [...workflowContent.matchAll(/src\/tests\/load\/k6\/scenarios\/([\w-]+\.js)/g)].map(
        (match) => match[1],
      ),
    ),
  ].sort();
}

/** The scenario files the nightly workflow runs: `{ name, content }`. */
export function loadNightlyScenarioFiles() {
  const names = new Set(nightlyScenarioNames(readFileSync(NIGHTLY_WORKFLOW_FILE, 'utf8')));
  return loadScenarioFiles().filter((scenario) => names.has(scenario.name));
}

/** Reads docs/routes.txt into routes (see {@link parseRoutes}). */
export function loadRoutes() {
  return parseRoutes(readFileSync(ROUTES_FILE, 'utf8'));
}

// --------------------------------------------------------------------------
// Coverage
// --------------------------------------------------------------------------

function routePattern(path) {
  const relative = path.replace(/^\/api\/v\d+/, '');
  const escaped = relative
    .split('/')
    .map((segment) =>
      segment.startsWith(':') ? '[^/]+' : segment.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'),
    )
    .join('/');
  return new RegExp(`^${escaped}$`);
}

/**
 * Matches scenario requests to the required routes: `{ required, covered, uncovered, excluded,
 * coveringFiles }`, where `coveringFiles` maps a covered route to the scenario files that call it.
 */
export function computeCoverage({ routes, scenarios }) {
  const requests = scenarios.flatMap((scenario) =>
    extractScenarioRequests(scenario.content).map((request) => ({
      ...request,
      file: scenario.name,
    })),
  );
  const required = routes.filter((route) => !isExcluded(route));
  const coveringFiles = new Map();
  for (const route of required) {
    const pattern = routePattern(route.path);
    const files = [
      ...new Set(
        requests
          .filter((request) => request.method === route.method && pattern.test(request.path))
          .map((request) => request.file),
      ),
    ];
    if (files.length > 0) coveringFiles.set(route, files);
  }
  return {
    required,
    covered: required.filter((route) => coveringFiles.has(route)),
    uncovered: required.filter((route) => !coveringFiles.has(route)),
    excluded: routes.filter((route) => isExcluded(route)),
    coveringFiles,
  };
}

// --------------------------------------------------------------------------
// CLI
// --------------------------------------------------------------------------

function main() {
  const args = process.argv.slice(2);
  const reportOnly = args.includes('--report-only');
  const nightly = args.includes('--nightly');
  const thresholdIndex = args.indexOf('--threshold');
  const threshold = thresholdIndex !== -1 ? Number(args[thresholdIndex + 1]) : DEFAULT_THRESHOLD;

  let routes;
  try {
    routes = loadRoutes();
  } catch {
    console.error(
      `check-load-coverage: cannot read ${ROUTES_FILE} — run pnpm routes:catalog first`,
    );
    process.exit(reportOnly ? 0 : 1);
  }
  const scenarios = nightly ? loadNightlyScenarioFiles() : loadScenarioFiles();
  const { required, covered, uncovered, excluded } = computeCoverage({ routes, scenarios });
  const percentage =
    required.length === 0 ? 100 : Math.round((covered.length / required.length) * 100);

  const GREEN = '\x1b[32m';
  const YELLOW = '\x1b[33m';
  const RED = '\x1b[31m';
  const DIM = '\x1b[2m';
  const RESET = '\x1b[0m';

  console.log('\n─────────────────────────────────────────────────────────');
  console.log(
    `  k6 Load-test Route Coverage (${nightly ? 'nightly workflow' : 'all scenario files'})`,
  );
  console.log('─────────────────────────────────────────────────────────');
  console.log(`  Scenario files     : ${scenarios.length}`);
  console.log(`  Total routes       : ${routes.length}`);
  console.log(
    `  Excluded           : ${excluded.length}  ${DIM}(ROLE / TOKEN / public infrastructure)${RESET}`,
  );
  console.log(`  Required (testable): ${required.length}`);
  console.log(`  Covered            : ${covered.length}  ${GREEN}✓${RESET}`);
  console.log(
    `  Uncovered          : ${uncovered.length}  ${uncovered.length > 0 ? `${YELLOW}⚠` : `${GREEN}✓`}${RESET}`,
  );
  console.log(
    `  Coverage           : ${percentage >= threshold ? GREEN : RED}${percentage}%${RESET}  (threshold: ${threshold}%)`,
  );
  console.log('─────────────────────────────────────────────────────────\n');

  if (uncovered.length > 0) {
    console.log(`${YELLOW}Uncovered routes — add to a k6 scenario to improve coverage:${RESET}`);
    for (const route of uncovered) {
      console.log(
        `  ${DIM}${route.method.padEnd(7)}${RESET} ${route.path}  ${DIM}${route.auth}${RESET}`,
      );
    }
    console.log('');
  }

  if (percentage < threshold) {
    if (reportOnly) {
      console.log(
        `${YELLOW}⚠ check-load-coverage: ${percentage}% < ${threshold}% — below threshold (report-only, not failing)${RESET}\n`,
      );
      return;
    }
    console.error(
      `${RED}✗ check-load-coverage: ${percentage}% < threshold ${threshold}% — failing build.${RESET}\n`,
    );
    process.exit(1);
  }
  console.log(`${GREEN}✓ check-load-coverage: ${percentage}% ≥ ${threshold}% — OK${RESET}\n`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}
